import{_ as i,o as a,c as n,ai as t}from"./chunks/framework.BxxKhjs3.js";const e="/pub-blog/assets/image-20260126114359582.CIhoC3DD.png",l="/pub-blog/assets/image-20260126114443371.BA6S-6x2.png",p="/pub-blog/assets/image-20260126114519279.CvBXZ3d8.png",h="/pub-blog/assets/image-20260126114710834.DPXTjmbc.png",d="data:image/png;base64,",r="/pub-blog/assets/image-20260126115024831.CIVmb6rb.png",k="/pub-blog/assets/image-20260126115223428.DJudWOI3.png",o="/pub-blog/assets/image-20260126115324670.Bwkisa9z.png",c="/pub-blog/assets/image-20260126115402319.It9mOakA.png",g="/pub-blog/assets/image-20260126115501861.Brzm35jM.png",F="/pub-blog/assets/image-20260126115641356.BD3KSna4.png",b="/pub-blog/assets/image-20260126122307599.v6qXa3cr.png",u="/pub-blog/assets/image-20260126122354566.C0ESjjSz.png",m="/pub-blog/assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.KtucpRsB.jpg",w=JSON.parse('{"title":"一文教你使用免费的GLM4.7，从此告别token焦虑（vscode 、DevEco Studio也能直接使用）","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/一文教你使用免费的GLM4.7，从此告别token焦虑/一文教你使用免费的GLM4.7，从此告别token焦虑.md","filePath":"AI人工智能/一文教你使用免费的GLM4.7，从此告别token焦虑/一文教你使用免费的GLM4.7，从此告别token焦虑.md","lastUpdated":1769402654000,"__rawMarkdown":"# 一文教你使用免费的GLM4.7，从此告别token焦虑（vscode 、DevEco Studio也能直接使用）\\n\\n> 万少：华为HDE、鸿蒙极客\\n>\\n> 个人主页：https://blog.zbztb.cn/\\n>\\n> **2025年参与孵化了20+鸿蒙应用、技术文章300+、鸿蒙知识库用户500+、鸿蒙免费课程2套。**\\n>\\n> 如果你也喜欢交流AI和鸿蒙技术，欢迎扣我。\\n\\n最近的**GLM4.7**可谓是刷屏了，不少小伙伴在使用的时候也是直呼真香\\n\\nGLM4.7使用的方式不少：\\n\\n1. 一些国产的AI编辑器直接内置，例如**Trae**和**CodeBuddy**等\\n\\n   ![](assets/image-20260126114359582.png)\\n\\n2. 也可以付费买**token**，如claude code 可以接入 **GLM4.7**。\\n\\n   ![](assets/image-20260126114443371.png)\\n\\n3. 第三种就是推荐的，使用 阿里心流团队推出的**iflow-cli**，它针对个人免费使用，虽然是以终端的方式使用（类似cladue code），但是也可以通过插件的方式接入**vscode、DevEco Studio（Idea）**等主流编辑器，很容易就能上手。\\n\\n\\n\\n## iflow-cli\\n\\n> https://platform.iflow.cn/cli/quickstart\\n\\n![](assets/image-20260126114519279.png)\\n\\niFlow CLI 是一款终端AI助手，可以分析代码、执行编程任务、处理文件操作。\\n\\n内置免费国产优秀大模型，DeepSeek、QWen、GLM(支持GLM4.7)、K2等。\\n\\n![](assets/image-20260126114710834.png)\\n\\n## 第1步：安装（2分钟）\\n\\n### 系统要求\\n\\n- Node.js 22+\\n- 4GB+ 内存\\n- 互联网连接\\n\\n### 快速安装\\n\\n**macOS/Linux**\\n\\n```shell\\n# 一键安装脚本，会安装全部所需依赖\\nbash -c \\"$(curl -fsSL https://gitee.com/iflow-ai/iflow-cli/raw/main/install.sh)\\"\\n\\n# 已有Node.js 22+\\nnpm i -g @iflow-ai/iflow-cli@latest\\n```\\n\\n\\n\\n**Windows**\\n\\n```shell\\n1. 访问 https://nodejs.org/zh-cn/download 下载最新的 Node.js 安装程序\\n2. 运行安装程序来安装 Node.js\\n3. 重启终端：CMD(Windows + r 输入cmd) 或 PowerShell\\n4. 运行 `npm install -g @iflow-ai/iflow-cli@latest` 来安装 iFlow CLI\\n5. 运行 `iflow` 来启动 iFlow CLI\\n```\\n\\n\\n\\n> **推荐使用 Windows Terminal**：为了获得更好的兼容性和使用体验，强烈推荐使用 [Windows Terminal](https://apps.microsoft.com/detail/9n0dx20hk701) 运行 iFlow CLI，可以大幅减少环境兼容性问题。\\n>\\n> **验证安装**：运行 `iflow --version` 确认安装成功\\n\\n## 第2步：首次设置（1分钟）\\n\\n### 启动iFlow\\n\\n```shell\\niflow\\n```\\n\\n![](assets/image-20260126114834406.png)\\n\\n首次打开，可能需要你跳转到网页进行登录。\\n\\n登录成功后，会出现以下界面。\\n\\n![](assets/image-20260126115024831.png)\\n\\n可以看到是支持GLM4.7模型的，另外可以按tab开启思考模式，让操作更加智能！\\n\\n\\n\\n## 第3步：接入vscode\\n\\nvscode中搜索插件 **iflow-cli** ， 然后直接安装即可。\\n\\n![](assets/image-20260126115223428.png)\\n\\n安装成功后，随便打开一个文件，会在状态栏上看到图标。\\n\\n![](assets/image-20260126115324670.png)\\n\\n点击它，会在当前目录打开终端\\n\\n![](assets/image-20260126115402319.png)\\n\\n接下来你可以在终端中直接对话，也可以鼠标选中代码片段进行沟通。\\n\\n![](assets/image-20260126115501861.png)\\n\\n接下来可以畅享免费的AI编辑了！\\n\\n## 第4步：接入 DevEco Studio\\n\\n如果是做鸿蒙应用开发，就需要下载离线插件，下载地址如下：\\n\\n> https://platform.iflow.cn/cli/features/ide\\n\\n![](assets/image-20260126115641356.png)\\n\\n下载到本地后，使用DevEco Studio 离线安装即可\\n\\n![](assets/image-20260126122307599.png)\\n\\n安装成功后，重启开发工具，最后顶部菜单栏上也有**iflow的图标**展示。\\n\\n![](assets/image-20260126122354566.png)\\n\\n## 实用技巧\\n\\n| 命令                | 功能         | 说明                                      |\\n| ------------------- | ------------ | ----------------------------------------- |\\n| `/about`            | 系统信息     | 显示CLI版本、操作系统、模型版本等综合信息 |\\n| `/auth`             | 身份验证     | 配置或更改身份验证提供商                  |\\n| `/theme`            | 主题设置     | 自定义CLI外观主题                         |\\n| `/model`            | 模型切换     | 更改正在使用的AI模型                      |\\n| `/editor`           | 编辑器配置   | 配置首选的外部编辑器                      |\\n| `/privacy`          | 隐私信息     | 显示隐私通知和数据处理信息                |\\n| `/language`         | 语言设置     | 切换CLI界面语言 (zh-CN/en-US)             |\\n| `/output-style`     | 输出样式     | 设置AI输出样式和格式                      |\\n| `/output-style:new` | 创建输出样式 | 基于描述创建新的AI输出样式                |\\n| `/update`           | 软件更新     | 检查并更新CLI到最新版本                   |\\n\\n### 会话控制命令\\n\\n| 命令                  | 功能       | 说明                         |\\n| --------------------- | ---------- | ---------------------------- |\\n| `/chat`               | 对话管理   | 保存、恢复、删除对话检查点   |\\n| `/clear`              | 清屏重置   | 清除屏幕并重置对话历史       |\\n| `/compress`           | 内容压缩   | 使用AI将对话历史压缩为摘要   |\\n| `/memory`             | 内容管理   | 与CLI的内容系统交互          |\\n| `/restore`            | 状态恢复   | 恢复到之前的检查点状态       |\\n| `/resume`             | 会话恢复   | 恢复之前的对话会话           |\\n| `/quit`               | 退出程序   | 退出CLI会话并显示统计信息    |\\n| `/cleanup-history`    | 清理历史   | 打开清理对话历史记录的对话框 |\\n| `/cleanup-checkpoint` | 清理检查点 | 打开清理对话检查点的对话框   |\\n\\n### 工具集成命令\\n\\n| 命令          | 功能     | 说明                          |\\n| ------------- | -------- | ----------------------------- |\\n| `/ide`        | IDE集成  | 发现和连接到可用的IDE服务器   |\\n| `/mcp`        | MCP管理  | 管理MCP服务器、工具和身份验证 |\\n| `/tools`      | 工具列表 | 列出所有可用的内置CLI工具     |\\n| `/extensions` | 扩展管理 | 显示当前活动的扩展及版本      |\\n\\n### 开发辅助命令\\n\\n| 命令            | 功能       | 说明                                                        |\\n| --------------- | ---------- | ----------------------------------------------------------- |\\n| `/init`         | 项目初始化 | 分析项目并创建定制的配置文件                                |\\n| `/setup-github` | GitHub配置 | 配置GitHub Actions工作流                                    |\\n| `/directory`    | 目录管理   | 管理工作空间目录以获得项目上下文                            |\\n| `/export`       | 导出功能   | 以各种格式导出对话历史                                      |\\n| `/copy`         | 复制功能   | 将最后的AI响应复制到剪贴板                                  |\\n| `/demo`         | 演示模式   | 启动交互式演示和教程模式                                    |\\n| `/qa`           | 问答助手   | 基于知识库的智能问答助手 (别名: /wenwen, /question, /guide) |\\n\\n### 监控调试命令\\n\\n| 命令     | 功能     | 说明                       |\\n| -------- | -------- | -------------------------- |\\n| `/stats` | 统计信息 | 监控会话使用情况和性能统计 |\\n| `/log`   | 日志位置 | 显示当前会话日志存储位置   |\\n| `/bug`   | 错误报告 | 提交带有系统信息的错误报告 |\\n| `/help`  | 帮助信息 | 打开综合帮助对话框         |\\n| `/docs`  | 文档访问 | 在浏览器中打开完整文档     |\\n\\n### 特殊功能命令\\n\\n| 命令              | 功能     | 说明                         |\\n| ----------------- | -------- | ---------------------------- |\\n| `/vim`            | Vim模式  | 切换vim风格按键绑定          |\\n| `/corgi`          | 特殊主题 | 切换柯基主题UI模式（彩蛋）   |\\n| `/commands`       | 命令市场 | 管理和安装自定义命令         |\\n| `/agents`         | 代理管理 | 管理个人、项目和内置代理     |\\n| `/terminal-setup` | 终端设置 | 配置终端键绑定以支持多行输入 |\\n\\n### 常见使用场景\\n\\n#### 系统配置\\n\\n```bash\\n/about                      # 查看系统信息\\n/auth                       # 配置身份验证\\n/model                      # 切换AI模型\\n/theme                      # 更改主题\\n```\\n\\n\\n\\n#### 会话管理\\n\\n```bash\\n/chat list                  # 列出所有保存的对话\\n/chat save project-review   # 保存对话检查点\\n/chat resume project-review # 恢复指定的对话\\n/chat delete project-review # 删除指定的对话\\n/memory show                # 显示当前记忆内容\\n/memory add \\"项目使用React\\" # 添加记忆信息\\n/memory refresh             # 刷新记忆内容\\n/memory list                # 列出记忆文件列表\\n/compress                   # 压缩对话历史\\n/clear                      # 清空会话\\n/resume                     # 恢复之前的会话\\n```\\n\\n\\n\\n#### 开发辅助\\n\\n```bash\\n/init                       # 初始化项目配置\\n/ide                        # 连接IDE\\n/mcp list                   # 列出所有MCP服务器\\n/mcp auth <server>          # 配置MCP服务器身份验证\\n/mcp online                 # 浏览在线MCP服务器\\n/mcp refresh                # 刷新MCP服务器连接\\n/directory add <path>       # 添加工作空间目录\\n/directory show             # 显示当前工作空间目录\\n/export clipboard           # 导出对话到剪贴板\\n/export file                # 导出对话到文件\\n```\\n\\n\\n\\n#### 调试支持\\n\\n```bash\\n/stats                      # 查看会话统计\\n/stats model                # 查看模型使用统计\\n/stats tools                # 查看工具使用统计\\n/log                        # 查看日志位置\\n/bug \\"描述问题\\"             # 提交错误报告\\n/help                       # 获取帮助\\n```\\n\\n\\n\\n#### 系统和界面配置\\n\\n```bash\\n/language zh-CN            # 切换到中文界面\\n/language en-US            # 切换到英文界面\\n/output-style professional # 使用专业输出样式\\n/output-style:new \\"简洁风格\\" # 创建新的输出样式\\n/update                    # 检查并更新CLI版本\\n```\\n\\n\\n\\n#### 对话和历史管理\\n\\n```bash\\n/cleanup-history            # 清理对话历史记录\\n/cleanup-checkpoint         # 清理对话检查点\\n/demo                       # 启动演示模式\\n/qa \\"如何使用MCP?\\"          # 基于知识库的问答\\n/agents list                # 列出所有可用的代理\\n/agents refresh             # 刷新代理列表\\n/agents online              # 浏览在线代理市场\\n/agents install             # 安装代理\\n/commands list              # 列出本地自定义命令\\n/commands online            # 浏览在线命令市场\\n/commands get <id>          # 获取指定ID的命令\\n/terminal-setup             # 配置终端以支持多行输入\\n```\\n\\n**关注我**，持续分享鸿蒙开发 + AI 提效的实战技巧。\\n\\n![](assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.jpg)"}'),y={name:"AI人工智能/一文教你使用免费的GLM4.7，从此告别token焦虑/一文教你使用免费的GLM4.7，从此告别token焦虑.md"};function C(A,s,B,D,v,E){return a(),n("div",null,[...s[0]||(s[0]=[t("",73)])])}const q=i(y,[["render",C]]);export{w as __pageData,q as default};
